import { NextResponse } from "next/server";
import prisma from "@/lib/prisma";
import { ensureFallbackZone } from "@/lib/zoneMatcher";
import { generateTrackToken } from "@/lib/tracking";
import { requireServerRole } from "@/lib/server-permissions";

// Shared Prisma client singleton (see lib/prisma.ts) — one client per process, reused across requests.

// ── Autogenerated merchant order ID helper ──────────────────────────────
// Produces sequential IDs in the format "{merchantId}-{seq}" (e.g. 2-0001,
// 2-0002, ...). The sequence is derived from the merchant's existing orderIds
// matching this pattern, so deletions never reuse a number.
async function generateMerchantOrderId(
  merchantCuid: string,
  merchantNum: number,
): Promise<string> {
  const existing = await prisma.order.findMany({
    where: { merchantId: merchantCuid },
    select: { orderId: true },
  });

  let maxSeq = 0;
  const pattern = new RegExp(`^${merchantNum}-(\\d+)$`);
  for (const o of existing) {
    const match = o.orderId.match(pattern);
    if (match) {
      const seq = parseInt(match[1], 10);
      if (seq > maxSeq) maxSeq = seq;
    }
  }

  return `${merchantNum}-${String(maxSeq + 1).padStart(4, "0")}`;
}

// POST /api/merchant/orders — Merchant-scoped order creation
// The merchantId is programmatically injected from the authenticated session.
export async function POST(request: Request) {
  try {
    // ── Authenticate via session cookie ──────────────────────────────────
    // The role is re-read from the database (not the stale 24-hour token
    // claim) so a role change takes effect immediately.
    const auth = await requireServerRole(request, "MERCHANT");
    if (auth instanceof Response) return auth;
    const user = auth.user;

    // ── Resolve merchant profile from session userId ─────────────────────
    const merchant = await prisma.merchant.findUnique({
      where: { userId: user.id },
      select: { id: true, merchantId: true },
    });

    if (!merchant) {
      return NextResponse.json(
        { error: "No merchant profile linked to your account" },
        { status: 403 },
      );
    }

    // ── Parse request body ───────────────────────────────────────────────
    const body = await request.json();
    const finalPrice = body.price || body.amountUsd;

    if (!body.customerName)
      return NextResponse.json(
        { error: "Missing Customer Name" },
        { status: 400 },
      );

    const parsedPrice = parseFloat(finalPrice);
    const amountUsd = isNaN(parsedPrice) ? 0 : parsedPrice;

    const parsedLbp = parseFloat(body.amountLbp);
    const amountLbp = isNaN(parsedLbp) ? 0 : parsedLbp;

    const parsedExtraShipping = parseFloat(body.extraShipping);
    const extraShipping = isNaN(parsedExtraShipping) ? 0 : parsedExtraShipping;

    const parsedPackages = parseInt(body.packages);
    const packages = isNaN(parsedPackages) ? 1 : parsedPackages;

    // ── Default zone for merchant-created orders ─────────────────────────
    // Merchants no longer pick a zone. The order starts in the "CP" (customer
    // pickup) warehouse under the fallback zone "99"; the correct delivery zone
    // is assigned automatically when staff move the order to the warehouse.
    const zoneId = await ensureFallbackZone();

    // ── Create order with programmatically injected merchantId ────────────
    // The order ID is autogenerated as "{merchantId}-{seq}" (e.g. 2-0001).
    // A P2002 collision (two concurrent creates) regenerates the ID and retries.
    let newOrder;
    const trackToken = await generateTrackToken();
    for (let attempt = 1; attempt <= 5; attempt++) {
      const orderId = await generateMerchantOrderId(
        merchant.id,
        merchant.merchantId,
      );
      try {
        newOrder = await prisma.order.create({
          data: {
            orderId,
            trackToken,
            customerName: body.customerName,
            customerPhone: body.customerPhone || "N/A",
            customerAddress: body.customerAddress || "N/A",
            packages: packages,
            zoneId,
            // Merchant orders are staged in the CP warehouse until staff move
            // them into the main warehouse.
            location: "CP",
            hasExchange: body.hasExchange === true || body.hasExchange === "true",
            amountUsd: amountUsd,
            amountLbp: amountLbp,
            extraShipping: extraShipping,
            // ── Security: merchantId injected from session, never from body ──
            merchantId: merchant.id,
            creatorId: user.id,
            notes: body.notes || null,
            history: {
              create: {
                action: "Order Created by Merchant",
                location: "CP",
                userId: user.id,
              },
            },
          },
        });
        break;
      } catch (error: unknown) {
        const code = (error as { code?: string })?.code;
        if (code === "P2002" && attempt < 5) continue;
        throw error;
      }
    }

    return NextResponse.json(newOrder, { status: 201 });
  } catch (error: unknown) {
    // Log the full error server-side; the client gets a generic message so
    // internal exception detail is never returned.
    console.error("[POST /api/merchant/orders] Error:", error);
    // Duplicate order IDs are the one expected conflict — surface it without
    // leaking internal detail.
    const code = (error as { code?: string })?.code;
    if (code === "P2002") {
      return NextResponse.json(
        { error: "An order with this ID already exists" },
        { status: 400 },
      );
    }
    return NextResponse.json(
      { error: "Failed to create order" },
      { status: 500 },
    );
  }
}
